73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
81	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
82	     * addresses are lower-cased before being stored.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
86	
87	    /** An owner's postcode, when supplied, must be exactly four digits. */
88	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
89	
90	    /**
91	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
92	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
93	     */
94	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
95	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
96	
97	    /**
98	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
99	     * named logger keeps them addressable independently of the class's diagnostic logging.
100	     */
101	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
102	
103	    /**
104	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
105	     * audit event. It is process-wide (static) so the ordering holds across every owner created,
106	     * regardless of which controller instance handles the request.
107	     */
108	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong(0);
109	
110	    /** Serializes the immutable structured audit event to its canonical JSON representation. */
111	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
112	
113	    /**
114	     * Maximum number of owners a single city may contain. A create that would take the owner's city
115	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
116	     */
117	    private static final int CITY_OWNER_LIMIT = 50;
118	
119	    /**
120	     * Number of owners a city must already hold for a create response and owner read to flag that the
121	     * city is approaching capacity. When the city holds between this many and {@link #CITY_OWNER_LIMIT}
122	     * minus one owners (40-49), the owner's {@code capacityWarning} is {@code true}; the hard rejection
123	     * at {@link #CITY_OWNER_LIMIT} is unchanged.
124	     */
125	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
126	
127	    /**
128	     * Maximum number of owners that may be registered on a single day. A create that would take the
129	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
130	     * have already been created that day - is rejected with a 429.
131	     */
132	    private static final int DAILY_OWNER_LIMIT = 100;
133	
134	    /**
135	     * Number of owners that must already have been created for a given day before the create
136	     * response flags a bulk sign-up. When more than this many owners already share a
137	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
138	     */
139	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
140	
141	    /**
142	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
143	     * like a weekend and rolled forward to the next non-holiday business day.
144	     */
145	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
146	        LocalDate.of(2026, 1, 1),
147	        LocalDate.of(2026, 1, 26),
148	        LocalDate.of(2026, 4, 25),
149	        LocalDate.of(2026, 12, 25),
150	        LocalDate.of(2026, 12, 28));
151	
152	    /**
153	     * Request header carrying the client-supplied idempotency key. When a create repeats with a key
154	     * already seen, the originally created owner is returned instead of creating a duplicate.
155	     */
156	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
157	
158	    private final ClinicService clinicService;
159	
160	    private final OwnerMapper ownerMapper;
161	
162	    private final PetMapper petMapper;
163	
164	    private final VisitMapper visitMapper;
165	
166	    private final HttpServletRequest request;
167	
168	    /**
169	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
170	     * create with an already-seen key returns the originally created owner rather than a duplicate.
171	     */
172	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
173	
174	    public OwnerRestControllerV1(ClinicService clinicService,
175	                                 OwnerMapper ownerMapper,
176	                                 PetMapper petMapper,
177	                                 VisitMapper visitMapper,
178	                                 HttpServletRequest request) {
179	        this.clinicService = clinicService;
180	        this.ownerMapper = ownerMapper;
181	        this.petMapper = petMapper;
182	        this.visitMapper = visitMapper;
183	        this.request = request;
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
189	        Collection<Owner> owners;
190	        if (lastName != null) {
191	            owners = this.clinicService.findOwnerByLastName(lastName);
192	        } else {
193	            owners = this.clinicService.findAllOwners();
194	        }
195	        if (owners.isEmpty()) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
209	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
210	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
211	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
212	    }
213	
214	    /**
215	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
216	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
217	     * owner sign-ups.
218	     *
219	     * @param registrationDate the day to inspect, or {@code null}
220	     * @return {@code true} when more than the threshold of owners are registered on that day
221	     */
222	    private boolean isBulkSignupDay(LocalDate registrationDate) {
223	        return registrationDate != null
224	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
225	    }
226	
227	    /**
228	     * Determines whether the supplied city is approaching its per-city capacity, i.e. it currently
229	     * holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_LIMIT} minus one
230	     * owners (40-49). This flags a city nearing the hard limit of {@link #CITY_OWNER_LIMIT}; that hard
231	     * rejection is unchanged.
232	     *
233	     * @param city the city to inspect, or {@code null}
234	     * @return {@code true} when the city holds 40-49 owners
235	     */
236	    private boolean isApproachingCityCapacity(String city) {
237	        if (city == null) {
238	            return false;
239	        }
240	        long count = countOwnersInCity(city);
241	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
247	        String idempotencyKey = idempotencyKey();
248	        if (idempotencyKey != null) {
249	            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
250	            if (existing != null) {
251	                return new ResponseEntity<>(existing, HttpStatus.OK);
252	            }
253	        }
254	        Owner owner = buildOwnerToCreate(ownerFieldsDto);
255	        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
256	        finalizeOwnerForCreate(owner);
257	        this.clinicService.saveOwner(owner);
258	        ResponseEntity<OwnerDto> response = createdOwnerResponse(owner, bulkSignupWarning);
259	        if (idempotencyKey != null) {
260	            this.idempotencyStore.put(idempotencyKey, response.getBody());
261	        }
262	        return response;
263	    }
264	
265	    /**
266	     * Returns the client-supplied {@code Idempotency-Key} for the current request, or {@code null}
267	     * when the header is absent or blank.
268	     */
269	    private String idempotencyKey() {
270	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
271	        return StringUtils.hasText(key) ? key : null;
272	    }
273	
274	    /**
275	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
276	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
277	     * submitted address is canonicalized, the required fields and the optional postcode and
278	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
279	     * registration date is defaulted to the server date when absent and rolled forward to a business
280	     * day. The household id and identity key are derived; a create whose identity key matches an
281	     * existing, non-deleted owner is rejected with a 409 unless it opts in with {@code sharesHousehold},
282	     * and otherwise a soft-match duplicate is flagged.
283	     *
284	     * @param ownerFieldsDto the submitted owner fields
285	     * @return the normalized owner, not yet persisted
286	     */
287	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
288	        resolveAddressFields(ownerFieldsDto);
289	        validateRequiredFields(ownerFieldsDto);
290	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
291	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
292	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
293	        owner.setEmail(normalizeEmail(owner.getEmail()));
294	        validateRegistrationDate(owner.getRegistrationDate());
295	        if (owner.getRegistrationDate() == null) {
296	            owner.setRegistrationDate(LocalDate.now());
297	        }
298	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
299	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
300	        resolveHouseholdIdentity(owner, sharesHousehold);
301	        return owner;
302	    }
303	
304	    /**
305	     * Places the owner about to be created into its household and settles its identity against the
306	     * owners already on file. The owner's {@code householdId} is still derived deterministically from
307	     * its last name and postcode (it drives the household size and membership-level cap), but identity
308	     * is now decided solely by the {@code identityKey}, the SHA-256 digest over the normalized
309	     * telephone, email and the last name's Soundex code. Unless the request opted into a shared
310	     * household, an owner whose identity key matches any existing, non-deleted owner is rejected with a
311	     * 409; and, again only when the household was not opted into, a soft-match against an existing owner
312	     * flags the new owner as a possible duplicate. Two owners sharing a last name and postcode but with
313	     * different telephones now derive different identity keys, so they are admitted (as a soft match)
314	     * rather than rejected, with their membership level later capped by
315	     * {@link #applyMembershipLevelCap(Owner)}.
316	     *
317	     * @param owner the normalized owner about to be created, with its contact details already normalized
318	     * @param sharesHousehold whether the request opted into joining an existing household
319	     */
320	    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
321	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
322	        owner.setIdentityKey(buildIdentityKey(owner));
323	        if (!sharesHousehold) {
324	            rejectDuplicateIdentity(owner);
325	        }
326	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
327	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
328	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
329	    }
330	
331	    /**
332	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
333	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
334	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
335	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
336	     * registration date, measured before it is saved, which the caller uses to decide the response's
337	     * {@code bulkSignupWarning}.
338	     *
339	     * @param owner the normalized owner about to be created
340	     * @return the number of owners already registered on the owner's registration date
341	     */
342	    private long enforceCreateLimits(Owner owner) {
343	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
344	            throw new OwnerCityFullException(owner.getCity());
345	        }
346	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
347	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
348	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
349	        }
350	        return ownersRegisteredOnDay;
351	    }
352	
353	    /**
354	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
355	     * de-duplicated customer code, the number of existing namesakes, the household size once the
356	     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
357	     *
358	     * @param owner the normalized owner about to be created
359	     */
360	    private void finalizeOwnerForCreate(Owner owner) {
361	        owner.setCustomerCode(buildCustomerCode(owner));
362	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
363	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
364	        applyMembershipLevelCap(owner);
365	    }
366	
367	    /**
368	     * Caps the membership level of an owner about to be created so it cannot exceed one above the
369	     * current maximum membership level among the owner's existing household members. The owner is not
370	     * yet persisted, so {@link #activeHouseholdMembers(String)} returns exactly the members already on
371	     * file; each member's effective (already-capped) level is read via
372	     * {@link org.springframework.samples.petclinic.mapper.MembershipLevel#forOwner(Owner)}. When the
373	     * household has no existing member no ceiling applies and the cap is left unset, so the owner keeps
374	     * its fully-derived level.
375	     *
376	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
377	     */
378	    private void applyMembershipLevelCap(Owner owner) {
379	        activeHouseholdMembers(owner.getHouseholdId()).stream()
380	            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
381	            .max()
382	            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
383	    }
384	
385	    /**
386	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
387	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
388	     * count, and adds the {@code Location} header pointing at the new owner.
389	     *
390	     * @param owner the owner that has just been saved, with its generated id populated
391	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
392	     * @return the created-owner response
393	     */
394	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
395	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
396	        logOwnerCreated(owner, ownerDto);
397	        emitOwnerCreatedEvent(owner, ownerDto);
398	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
399	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
400	        HttpHeaders headers = new HttpHeaders();
401	        headers.setLocation(UriComponentsBuilder.newInstance()
402	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
403	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
404	    }
405	
406	    /**
407	     * Emits the human-readable {@code OWNER_CREATED} audit line on the {@code AUDIT} logger, alongside
408	     * the structured event written by {@link #emitOwnerCreatedEvent}. The line records the owner's id,
409	     * customer code, registration date, membership level and membership number. Kept as its own method
410	     * so the response-builder stays focused on assembling the response and the single audit-line format
411	     * lives in one place.
412	     *
413	     * @param owner the owner that has just been saved, with its generated id populated
414	     * @param ownerDto the mapped DTO, source of the derived membership level and number
415	     */
416	    private void logOwnerCreated(Owner owner, OwnerDto ownerDto) {
417	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
418	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
419	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
420	    }
421	
422	    /**
423	     * Emits the immutable, structured {@code OWNER_CREATED} audit event on the {@code AUDIT} logger,
424	     * alongside the human-readable audit line. The event is a JSON object
425	     * {@code {seq, ownerId, customerCode, membershipLevel, event}} where {@code seq} is a
426	     * process-wide, monotonically increasing sequence across all creates. Its {@code customerCode}
427	     * field carries the owner's <em>current primary identifier</em> - the customer code today, and
428	     * whatever supersedes it later (for instance the member id once the two are unified) - as
429	     * returned by {@link #primaryIdentifier(Owner)}.
430	     *
431	     * @param owner the owner that has just been saved, with its generated id populated
432	     * @param ownerDto the mapped DTO, source of the derived membership level
433	     */
434	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
435	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(),
436	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(), "OWNER_CREATED");
437	        try {
438	            AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
439	        }
440	        catch (JacksonException e) {
441	            AUDIT.warn("failed to serialize OWNER_CREATED audit event for owner id={}", owner.getId(), e);
442	        }
443	    }
444	
445	    /**
446	     * Returns the owner's current primary identifier - the value the structured audit event carries
447	     * as its {@code customerCode}. Today that is the owner's customer code; when the customer code is
448	     * later unified into the member id, this is the single place that changes so the emitted event
449	     * carries the member id instead.
450	     *
451	     * @param owner the owner whose primary identifier is required
452	     * @return the owner's current primary identifier
453	     */
454	    private String primaryIdentifier(Owner owner) {
455	        return owner.getCustomerCode();
456	    }
457	
458	    /**
459	     * Immutable structured payload of an {@code OWNER_CREATED} audit event. The {@code customerCode}
460	     * field holds the owner's current primary identifier (see {@link #primaryIdentifier(Owner)}).
461	     */
462	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
463	        Integer membershipLevel, String event) {
464	    }
465	
466	    /**
467	     * Canonicalizes the submitted address fields into the form that is validated, stored and
468	     * returned, before any required-field check or mapping runs. This is the single place a create
469	     * request's address input is resolved.
470	     *
471	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
472	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
473	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
474	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
475	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
476	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
477	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
478	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
479	     * that is blank only after normalization is left blank here and rejected later by
480	     * {@link #validateRequiredFields}.
481	     *
482	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
483	     */
484	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
485	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
486	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
487	        if (!line1.isEmpty()) {
488	            ownerFieldsDto.setAddressLine1(line1);
489	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
490	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
491	        }
492	        else {
493	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
494	        }
495	    }
496	
497	    /**
498	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
499	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
500	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
501	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
502	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
503	     * normalization is still rejected.
504	     *
505	     * @param ownerFieldsDto the submitted owner fields
506	     */
507	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
508	        List<String> missingFields = new ArrayList<>();
509	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
510	            missingFields.add("firstName");
511	        }
512	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
513	            missingFields.add("lastName");
514	        }
515	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
516	            missingFields.add("address");
517	        }
518	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
519	            missingFields.add("city");
520	        }
521	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
522	            missingFields.add("telephone");
523	        }
524	        if (!missingFields.isEmpty()) {
525	            throw new MissingOwnerFieldsException(missingFields);
526	        }
527	    }
528	
529	    /**
530	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
531	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
532	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
533	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
534	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
535	     * whose {@code errors} array lists {@code postcode}.
536	     *
537	     * @param postcode the submitted postcode, or {@code null} when none was supplied
538	     * @param city the owner's city, whose region determines the acceptable postcode range
539	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
540	     */
541	    private void validatePostcode(String postcode, String city) {
542	        if (!StringUtils.hasText(postcode)) {
543	            return;
544	        }
545	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
546	            throw new InvalidOwnerFieldsException(List.of("postcode"));
547	        }
548	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
549	            throw new InvalidOwnerFieldsException(List.of("postcode"));
550	        }
551	    }
552	
553	    /**
554	     * Validates an owner's optional registration date. Registration date is optional, so a missing
555	     * value is accepted (the create later defaults it to the server date). When a value is supplied
556	     * it may not lie in the future: a date later than the server's current date is rejected with a
557	     * 400 whose {@code errors} array lists {@code registrationDate}.
558	     *
559	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
560	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
561	     */
562	    private void validateRegistrationDate(LocalDate registrationDate) {
563	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
564	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
565	        }
566	    }
567	
568	    /**
569	     * Rejects a submitted owner whose derived {@code identityKey} matches that of any existing,
570	     * non-deleted owner - the same normalized telephone, email and last-name Soundex, which marks the
571	     * same person being entered twice. This single identity key is the whole of duplicate detection:
572	     * because the telephone is part of the key, distinct people who merely share a last name and
573	     * postcode (but differ in telephone) derive a different key and so are admitted rather than
574	     * rejected. Soft-deleted owners are ignored, and the email-domain blocklist has already been
575	     * applied when the email was normalized. A genuine identity collision is reported to the client as
576	     * a 409 Conflict. A request may knowingly bypass this check by opting in with
577	     * {@code sharesHousehold}, in which case it is not performed.
578	     *
579	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
580	     */
581	    private void rejectDuplicateIdentity(Owner owner) {
582	        boolean identityInUse = this.clinicService.findAllOwners().stream()
583	            .filter(existing -> !existing.isDeleted())
584	            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
585	        if (identityInUse) {
586	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
587	        }
588	    }
589	
590	    /**
591	     * Returns the owners that currently belong to the household identified by {@code householdId} -
592	     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
593	     * because they no longer count as present members, so this is the household as it stands for the
594	     * owner being created. This is the single lookup of a household's current members behind the
595	     * household checks that reason about who is already there.
596	     *
597	     * @param householdId the derived household identifier to look up
598	     * @return the existing, non-deleted owners sharing that household, in no particular order
599	     */
600	    private List<Owner> activeHouseholdMembers(String householdId) {
601	        return this.clinicService.findAllOwners().stream()
602	            .filter(existing -> !existing.isDeleted())
603	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
604	            .collect(Collectors.toList());
605	    }
606	
607	    /**
608	     * Derives the owner's {@code identityKey} as the SHA-256 hex digest over
609	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone
610	     * and email have already been normalized (the email lower-cased, or the empty string when none was
611	     * supplied) and the last name is reduced to its {@link Soundex} code. Because the normalized
612	     * telephone is part of the key, two owners who differ only in telephone derive different identity
613	     * keys, so they are not the same identity even when they share a household.
614	     *
615	     * @param owner the normalized owner about to be created, with its contact details already normalized
616	     * @return the derived identity key, as 64 lower-case hex characters
617	     */
618	    private String buildIdentityKey(Owner owner) {
619	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
620	        return Sha256.hex(owner.getTelephone() + "|" + email + "|" + Soundex.encode(owner.getLastName()));
621	    }
622	
623	    /**
624	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner whose
625	     * derived {@code identityKey} differs from an existing owner's - so it is not the same identity, and
626	     * not a 409 - yet shares that owner's last-name {@link Soundex} code and {@code postcode}. Such an
627	     * owner is still created, but is flagged as a possible duplicate of the matching owner. In
628	     * particular, two owners with the same last name and postcode but different telephones now derive
629	     * different identity keys, so instead of the old hard household-duplicate rejection they surface
630	     * here as a soft match. This is only consulted for owners that did not opt into a shared household:
631	     * an owner that declares {@code sharesHousehold} is a known household member, not a suspected
632	     * duplicate, so it is never flagged. The comparison only applies when a postcode was supplied, since
633	     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
634	     *
635	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
636	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
637	     */
638	    private Integer findPossibleDuplicate(Owner owner) {
639	        if (!StringUtils.hasText(owner.getPostcode())) {
640	            return null;
641	        }
642	        String soundex = Soundex.encode(owner.getLastName());
643	        return this.clinicService.findAllOwners().stream()
644	            .filter(existing -> !existing.isDeleted())
645	            .filter(existing -> !owner.getIdentityKey().equals(existing.getIdentityKey()))
646	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
647	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
648	            .map(Owner::getId)
649	            .filter(id -> id != null)
650	            .min(Integer::compareTo)
651	            .orElse(null);
652	    }
653	
654	    /**
655	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
656	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
657	     * address; the accepted value is lower-cased before it is stored and returned.
658	     *
659	     * @param email the raw email value submitted by the client, or {@code null}
660	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
661	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
662	     */
663	    private String normalizeEmail(String email) {
664	        if (!StringUtils.hasText(email)) {
665	            return email;
666	        }
667	        if (!EMAIL_PATTERN.matcher(email).matches()) {
668	            throw new InvalidOwnerFieldsException(List.of("email"));
669	        }
670	        String normalized = email.toLowerCase();
671	        String domain = normalized.substring(normalized.indexOf('@') + 1);
672	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
673	            throw new InvalidOwnerFieldsException(List.of("email"));
674	        }
675	        return normalized;
676	    }
677	
678	    /**
679	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
680	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
681	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
682	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
683	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
684	     *
685	     * @param owner the normalized owner about to be created
686	     * @return the assigned, de-duplicated customer code
687	     */
688	    private String buildCustomerCode(Owner owner) {
689	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
690	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
691	        return deduplicateCustomerCode(code);
692	    }
693	
694	    /**
695	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
696	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
697	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
698	     *
699	     * @param code the composed customer code, before de-duplication
700	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
701	     */
702	    private String deduplicateCustomerCode(String code) {
703	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
704	            .map(Owner::getCustomerCode)
705	            .filter(existing -> existing != null)
706	            .collect(Collectors.toSet());
707	        if (!existingCodes.contains(code)) {
708	            return code;
709	        }
710	        int suffix = 2;
711	        while (existingCodes.contains(code + "-" + suffix)) {
712	            suffix++;
713	        }
714	        return code + "-" + suffix;
715	    }
716	
717	    /**
718	     * Counts how many owners already exist that share the supplied first and last name, compared
719	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
720	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
721	     *
722	     * @param firstName the submitted owner's first name
723	     * @param lastName the submitted owner's last name
724	     * @return the number of existing owners with the same first and last name, ignoring case
725	     */
726	    private int countNamesakes(String firstName, String lastName) {
727	        return (int) this.clinicService.findAllOwners().stream()
728	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
729	                && lastName.equalsIgnoreCase(existing.getLastName()))
730	            .count();
731	    }
732	
733	    /**
734	     * Counts how many existing owners already belong to the supplied household, identified by its
735	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
736	     * owner is added (this count plus one).
737	     *
738	     * @param householdId the normalized household identifier of the owner being created
739	     * @return the number of existing owners already sharing that {@code householdId}
740	     */
741	    private int countHouseholdMembers(String householdId) {
742	        return (int) this.clinicService.findAllOwners().stream()
743	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
744	            .count();
745	    }
746	
747	    /**
748	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
749	     * enforce the per-city capacity limit when a new owner is created.
750	     *
751	     * @param city the submitted owner's city
752	     * @return the number of existing owners in that city, ignoring case
753	     */
754	    private long countOwnersInCity(String city) {
755	        return this.clinicService.findAllOwners().stream()
756	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
757	            .count();
758	    }
759	
760	    /**
761	     * Counts how many owners have already been created on the supplied registration date. Used to
762	     * enforce the per-day capacity limit when a new owner is created.
763	     *
764	     * @param registrationDate the registration date of the owner being created
765	     * @return the number of existing owners already registered on that date
766	     */
767	    /**
768	     * Rolls a registration date forward to a business day. A registration date must fall on a
769	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
770	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
771	     * returned unchanged. Every value derived from the registration date (such as the membership
772	     * number's year segment) and the daily create-limit therefore use the adjusted date.
773	     *
774	     * @param date the effective registration date, whether supplied or defaulted to the server date
775	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
776	     */
777	    private LocalDate toBusinessDay(LocalDate date) {
778	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
779	            date = date.plusDays(1);
780	        }
781	        return date;
782	    }
783	
784	    private boolean isWeekend(LocalDate date) {
785	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
786	    }
787	
788	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
789	        return this.clinicService.findAllOwners().stream()
790	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
791	            .count();
792	    }
793	
794	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
795	    @Override
796	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
797	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
798	        if (currentOwner == null) {
799	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
800	        }
801	        currentOwner.setAddress(ownerFieldsDto.getAddress());
802	        currentOwner.setCity(ownerFieldsDto.getCity());
803	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
804	        currentOwner.setLastName(ownerFieldsDto.getLastName());
805	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
806	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
807	        this.clinicService.saveOwner(currentOwner);
808	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
809	    }
810	
811	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
812	    @Transactional
813	    @Override
814	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
815	        Owner owner = this.clinicService.findOwnerById(ownerId);
816	        if (owner == null) {
817	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
818	        }
819	        owner.setDeleted(true);
820	        this.clinicService.saveOwner(owner);
821	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
822	    }
823	
824	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
825	    @Override
826	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
827	        Owner owner = this.clinicService.findOwnerById(ownerId);
828	        if (owner == null) {
829	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
830	        }
831	        HttpHeaders headers = new HttpHeaders();
832	        Pet pet = petMapper.toPet(petFieldsDto);
833	        owner.setId(ownerId);
834	        pet.setOwner(owner);
835	        pet.getType().setName(null);
836	        this.clinicService.savePet(pet);
837	        PetDto petDto = petMapper.toPetDto(pet);
838	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
839	            .buildAndExpand(pet.getId()).toUri());
840	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
841	    }
842	
843	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
844	    @Override
845	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
846	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
847	        if (currentOwner != null) {
848	            Pet currentPet = this.clinicService.findPetById(petId);
849	            if (currentPet != null) {
850	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
851	                currentPet.setName(petFieldsDto.getName());
852	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
853	                this.clinicService.savePet(currentPet);
854	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
855	            }
856	        }
857	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
858	    }
859	
860	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
861	    @Override
862	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
863	        HttpHeaders headers = new HttpHeaders();
864	        Visit visit = visitMapper.toVisit(visitFieldsDto);
865	        Pet pet = new Pet();
866	        pet.setId(petId);
867	        visit.setPet(pet);
868	        this.clinicService.saveVisit(visit);
869	        VisitDto visitDto = visitMapper.toVisitDto(visit);
870	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
871	            .buildAndExpand(visit.getId()).toUri());
872	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
873	    }
874	
875	
876	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
877	    @Override
878	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
879	        Owner owner = this.clinicService.findOwnerById(ownerId);
880	        if (owner != null) {
881	            Pet pet = owner.getPet(petId);
882	            if (pet != null) {
883	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
884	            }
885	        }
886	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
887	    }
888	}
