                                      id         INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                      title      VARCHAR(10),
                                      first_name TEXT,
                                      last_name  TEXT,
                                      address    TEXT,
                                      city       TEXT,
                                      telephone  TEXT,
                                      email      TEXT,
                                      postcode   VARCHAR(4),
                                      registration_date DATE,
                                      customer_code TEXT,
                                      household_id TEXT,
                                      namesake_count INTEGER,
                                      household_size INTEGER,
                                      membership_level_cap INTEGER,
                                      identity_key TEXT,
                                      possible_duplicate BOOLEAN,
                                      possible_duplicate_of INTEGER,
                                      birth_date DATE,
                                      address_line1 TEXT,
                                      address_line2 TEXT,
